"""The offboarding pass — one guided admin action for a departing user (#1699).

Its own module beside `admin_members.py` and `admin_suites.py`: this composes
their primitives, it does not extend either axis.
"""

from __future__ import annotations

from typing import Annotated, Literal
from uuid import UUID

from fastapi import APIRouter, Depends
from pydantic import Field
from sqlalchemy.orm import Session

from backend.app.api.v1._base import ApiModel, ApiRequestModel
from backend.app.core.auth import require_workspace_admin
from backend.app.db.models import User
from backend.app.db.session import get_db
from backend.app.services import offboarding_service as svc

router = APIRouter(
    prefix="/admin",
    tags=["admin"],
    dependencies=[Depends(require_workspace_admin)],
)


class OwnedSuiteRead(ApiModel):
    id: UUID
    name: str
    check_count: int
    run_count: int
    result_count: int


class OffboardPreviewRead(ApiModel):
    user_id: UUID
    email: str
    display_name: str | None
    role: str
    #: True when the admin previewing this is the user being offboarded.
    is_self: bool
    #: The pass is refused while this is true — nothing below it would run.
    is_last_admin: bool
    #: `member` is the only state in which membership can be withdrawn here.
    membership_state: Literal["member", "not_a_member", "env_listed"]
    membership_id: UUID | None
    #: Why it cannot be, naming the env var when an allowlist is the reason.
    membership_note: str | None
    owned_suites: list[OwnedSuiteRead]
    #: Unrevoked, unexpired only — a PAT that already lapsed is not a live credential.
    open_api_key_count: int
    live_session_count: int


class OffboardRequest(ApiRequestModel):
    """`POST /admin/offboarding/{user_id}` body."""

    #: Required when the user owns any suite; ignored when they own none. A
    #: workspace viewer cannot inherit (422) — change their role first.
    new_owner_user_id: UUID | None = None
    #: The departing user keeps nothing by default — the opposite of the standalone
    #: transfer endpoint, because here they are leaving.
    keep_previous_owner_access: bool = False
    #: The user's own email address, typed by the admin. A mismatch is a 422.
    confirm_email: str = Field(min_length=3, max_length=320)


class OffboardReceiptRead(ApiModel):
    user_id: UUID
    email: str
    new_owner_user_id: UUID | None
    transferred_suite_ids: list[UUID]
    api_keys_revoked: int
    sessions_revoked: int
    membership_removed: bool
    #: Every step that did not run, with its reason — an empty list means all ran.
    skipped: list[dict[str, str]]


@router.get(
    "/offboarding/{user_id}/preview",
    response_model=OffboardPreviewRead,
    summary="What offboarding this user would do (admin)",
)
def preview_offboarding(
    user_id: UUID,
    current_user: Annotated[User, Depends(require_workspace_admin)],
    db: Annotated[Session, Depends(get_db)],
) -> OffboardPreviewRead:
    """Read-only. Nothing here is reserved or locked — a suite can change owner
    between this call and the pass, so treat the counts as of now.
    """
    view = svc.preview(db, user_id, actor=current_user)
    return OffboardPreviewRead(
        user_id=view.user_id,
        email=view.email,
        display_name=view.display_name,
        role=view.role,
        is_self=view.is_self,
        is_last_admin=view.is_last_admin,
        membership_state=view.membership_state,
        membership_id=view.membership_id,
        membership_note=view.membership_note,
        owned_suites=[
            OwnedSuiteRead(
                id=suite.id,
                name=suite.name,
                check_count=suite.check_count,
                run_count=suite.run_count,
                result_count=suite.result_count,
            )
            for suite in view.owned_suites
        ],
        open_api_key_count=view.open_api_key_count,
        live_session_count=view.live_session_count,
    )


@router.post(
    "/offboarding/{user_id}",
    response_model=OffboardReceiptRead,
    summary="Offboard a user in one audited pass (admin)",
)
def offboard_user(
    user_id: UUID,
    payload: OffboardRequest,
    current_user: Annotated[User, Depends(require_workspace_admin)],
    db: Annotated[Session, Depends(get_db)],
) -> OffboardReceiptRead:
    """Transfer every suite this user owns, revoke every PAT and browser session
    they hold, then withdraw their workspace membership — in one transaction.

    Their authored history stays: runs, results and checks keep pointing at them,
    and the user row itself is not deleted (erasure is the data-subject-rights
    endpoint, which is a different act). A step that cannot run is reported in
    `skipped` with its reason rather than silently passing.
    """
    receipt = svc.offboard(
        db,
        user_id,
        new_owner_user_id=payload.new_owner_user_id,
        confirm_email=payload.confirm_email,
        actor=current_user,
        keep_previous_owner_access=payload.keep_previous_owner_access,
    )
    return OffboardReceiptRead(
        user_id=receipt.user_id,
        email=receipt.email,
        new_owner_user_id=receipt.new_owner_user_id,
        transferred_suite_ids=receipt.transferred_suite_ids,
        api_keys_revoked=receipt.api_keys_revoked,
        sessions_revoked=receipt.sessions_revoked,
        membership_removed=receipt.membership_removed,
        skipped=receipt.skipped,
    )
import {
  Alert,
  App,
  Button,
  Descriptions,
  Flex,
  Input,
  List,
  Modal,
  Select,
  Spin,
  Tag,
  Typography,
} from 'antd';
import { useEffect, useRef, useState } from 'react';

import {
  type AdminUser,
  type OffboardPreview,
  type OffboardReceipt,
  offboardUser,
  previewOffboarding,
} from '../../api/admin';
import { searchUsers, type UserSummary } from '../../api/shares';
import { errorMessage } from '../../utils/errors';

/** Offboard a departing user in one pass: hand over their suites, revoke their
 *  PATs and browser sessions, withdraw their membership. Mount it keyed on the
 *  user — the preview and the picker are per-user and must not survive a
 *  different one being opened. */
export function OffboardModal({
  user,
  onClose,
  onOffboarded,
}: {
  /** `null` closes the modal. */
  user: AdminUser | null;
  onClose: () => void;
  onOffboarded: () => void;
}) {
  const { message } = App.useApp();
  const [preview, setPreview] = useState<OffboardPreview>();
  const [previewError, setPreviewError] = useState<string>();
  const [receipt, setReceipt] = useState<OffboardReceipt>();
  const [options, setOptions] = useState<UserSummary[]>([]);
  const [searching, setSearching] = useState(false);
  const [picked, setPicked] = useState<UserSummary>();
  const [typed, setTyped] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const latest = useRef(0);

  const userId = user?.id;

  // Fetch only. Per-user state is reset by REMOUNTING (the `key` in
  // `OffboardAction`), not by clearing it here — clearing state inside an effect
  // body cascades renders, and a stale receipt surviving into the next user's
  // modal is exactly the bug the key rules out.
  useEffect(() => {
    if (!userId) return;
    const controller = new AbortController();
    previewOffboarding(userId, controller.signal)
      .then(setPreview)
      .catch((err: unknown) => {
        if (!controller.signal.aborted) setPreviewError(errorMessage(err));
      });
    return () => controller.abort();
  }, [userId]);

  useEffect(
    () => () => {
      clearTimeout(timer.current);
      latest.current = -1;
    },
    [],
  );

  const onSearch = (raw: string) => {
    const q = raw.trim();
    clearTimeout(timer.current);
    if (q.length < 2) {
      setOptions([]);
      setSearching(false);
      return;
    }
    setSearching(true);
    const token = (latest.current += 1);
    timer.current = setTimeout(() => {
      searchUsers(q)
        .then((users) => {
          if (token !== latest.current) return;
          // A viewer cannot own a suite and the leaver cannot inherit their own —
          // the backend rejects both, so neither is offered.
          setOptions(users.filter((u) => u.role !== 'viewer' && u.id !== userId));
        })
        .catch(() => {
          if (token === latest.current) setOptions([]);
        })
        .finally(() => {
          if (token === latest.current) setSearching(false);
        });
    }, 300);
  };

  const needsOwner = (preview?.owned_suites.length ?? 0) > 0;
  const confirmed =
    preview !== undefined && typed.trim().toLowerCase() === preview.email.toLowerCase();
  const blocked = preview?.is_last_admin === true;
  const ready = confirmed && !blocked && (!needsOwner || picked !== undefined);

  const onOk = async () => {
    if (!userId || !preview || !ready) return;
    setSubmitting(true);
    try {
      const result = await offboardUser(userId, {
        new_owner_user_id: picked?.id ?? null,
        keep_previous_owner_access: false,
        confirm_email: preview.email,
      });
      setReceipt(result);
      message.success(`${preview.email} has been offboarded`);
      onOffboarded();
    } catch (err) {
      message.error(`Offboarding failed: ${errorMessage(err)}`);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Modal
      title={user ? `Offboard ${user.email}` : 'Offboard user'}
      open={user !== null}
      onCancel={onClose}
      onOk={receipt ? onClose : onOk}
      okText={receipt ? 'Done' : 'Offboard'}
      okButtonProps={{
        danger: !receipt,
        disabled: !receipt && !ready,
        loading: submitting,
      }}
      cancelButtonProps={{ style: receipt ? { display: 'none' } : undefined }}
      destroyOnHidden
      width={620}
    >
      {receipt ? (
        <Receipt receipt={receipt} />
      ) : previewError ? (
        <Alert
          type="error"
          showIcon
          title="Could not load the preview"
          description={previewError}
        />
      ) : !preview ? (
        <Spin size="large" />
      ) : (
        <Flex vertical gap={12}>
          {blocked && (
            <Alert
              type="error"
              showIcon
              title="This is the last admin in the workspace"
              description="Promote another admin first — offboarding this account would leave nobody able to administer the workspace."
            />
          )}
          {preview.is_self && (
            <Alert
              type="warning"
              showIcon
              title="This is you"
              description="Offboarding your own account signs you out and revokes your own tokens."
            />
          )}
          <Descriptions size="small" column={1} bordered>
            <Descriptions.Item label="Suites they own">
              {preview.owned_suites.length}
            </Descriptions.Item>
            <Descriptions.Item label="Personal access tokens">
              {preview.open_api_key_count} live
            </Descriptions.Item>
            <Descriptions.Item label="Browser sessions">
              {preview.live_session_count} live
            </Descriptions.Item>
            <Descriptions.Item label="Workspace membership">
              <MembershipNote preview={preview} />
            </Descriptions.Item>
          </Descriptions>
          {needsOwner && (
            <>
              <List
                size="small"
                bordered
                header={<Typography.Text strong>These suites need a new owner</Typography.Text>}
                dataSource={preview.owned_suites}
                renderItem={(suite) => (
                  <List.Item>
                    <Typography.Text>{suite.name}</Typography.Text>
                    <Typography.Text type="secondary">
                      {suite.check_count} check(s) · {suite.run_count} run(s)
                    </Typography.Text>
                  </List.Item>
                )}
              />
              <Select
                showSearch={{ filterOption: false, onSearch }}
                value={picked?.id}
                placeholder="Search by email or name"
                onChange={(id: string) => setPicked(options.find((u) => u.id === id))}
                notFoundContent={searching ? <Spin size="small" /> : null}
                options={options.map((u) => ({
                  value: u.id,
                  label: u.display_name ? `${u.display_name} · ${u.email}` : u.email,
                }))}
                aria-label="New owner"
              />
              <Typography.Text type="secondary">
                The departing user keeps no access to the suites they hand over. Workspace viewers
                can’t own a suite, so they aren’t listed.
              </Typography.Text>
            </>
          )}
          <Typography.Text>
            Type <Typography.Text code>{preview.email}</Typography.Text> to confirm.
          </Typography.Text>
          <Input
            value={typed}
            onChange={(e) => setTyped(e.target.value)}
            placeholder={preview.email}
            aria-label="Confirm email address"
            disabled={blocked}
          />
          <Typography.Text type="secondary">
            Their authored history stays: the runs, results and checks they created keep their name
            on them, and the account itself is not deleted.
          </Typography.Text>
        </Flex>
      )}
    </Modal>
  );
}

function MembershipNote({ preview }: { preview: OffboardPreview }) {
  if (preview.membership_state === 'member') return <Tag color="blue">will be withdrawn</Tag>;
  return (
    <Flex vertical gap={4}>
      <Tag color="orange">
        {preview.membership_state === 'env_listed' ? 'env-listed' : 'not a member'}
      </Tag>
      <Typography.Text type="secondary" style={{ fontSize: 12 }}>
        {preview.membership_note}
      </Typography.Text>
    </Flex>
  );
}

function Receipt({ receipt }: { receipt: OffboardReceipt }) {
  return (
    <Flex vertical gap={12}>
      <Alert type="success" showIcon title={`${receipt.email} has been offboarded`} />
      <Descriptions size="small" column={1} bordered>
        <Descriptions.Item label="Suites transferred">
          {receipt.transferred_suite_ids.length}
        </Descriptions.Item>
        <Descriptions.Item label="Tokens revoked">{receipt.api_keys_revoked}</Descriptions.Item>
        <Descriptions.Item label="Sessions revoked">{receipt.sessions_revoked}</Descriptions.Item>
        <Descriptions.Item label="Membership withdrawn">
          {receipt.membership_removed ? 'yes' : 'no'}
        </Descriptions.Item>
      </Descriptions>
      {receipt.skipped.length > 0 && (
        <List
          size="small"
          bordered
          header={<Typography.Text strong>Not done, and why</Typography.Text>}
          dataSource={receipt.skipped}
          renderItem={(step) => (
            <List.Item>
              <Typography.Text type="secondary">
                <Typography.Text code>{step.step}</Typography.Text> — {step.reason}
              </Typography.Text>
            </List.Item>
          )}
        />
      )}
    </Flex>
  );
}

/** The Members-table row action that opens the modal. */
export function OffboardAction({
  user,
  onOffboarded,
}: {
  user: AdminUser;
  onOffboarded: () => void;
}) {
  const [open, setOpen] = useState(false);
  return (
    <>
      <Button size="small" type="text" danger onClick={() => setOpen(true)}>
        Offboard
      </Button>
      <OffboardModal
        key={`${user.id}:${String(open)}`}
        user={open ? user : null}
        onClose={() => setOpen(false)}
        onOffboarded={onOffboarded}
      />
    </>
  );
}
import { Select, Spin } from 'antd';
import { type CSSProperties, useEffect, useRef, useState } from 'react';

import { searchUsers, type UserSummary } from '../../api/shares';

/** Debounced directory search that keeps the picked user as an object, so a later
 *  search replacing the options can never blank the selection. */
export function UserSearchSelect({
  value,
  onChange,
  exclude,
  placeholder = 'Search by email or name',
  ariaLabel,
  style,
}: {
  value: UserSummary | undefined;
  onChange: (user: UserSummary | undefined) => void;
  exclude?: (user: UserSummary) => boolean;
  placeholder?: string;
  ariaLabel?: string;
  style?: CSSProperties;
}) {
  const [options, setOptions] = useState<UserSummary[]>([]);
  const [searching, setSearching] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  // Last-wins token; unmount parks it on a sentinel so an in-flight response is dropped.
  const latest = useRef(0);
  useEffect(
    () => () => {
      clearTimeout(timer.current);
      latest.current = -1;
    },
    [],
  );

  const onSearch = (raw: string) => {
    const q = raw.trim();
    clearTimeout(timer.current);
    if (q.length < 2) {
      setOptions([]);
      setSearching(false);
      return;
    }
    setSearching(true);
    const token = (latest.current += 1);
    timer.current = setTimeout(() => {
      searchUsers(q)
        .then((users) => {
          if (token !== latest.current) return;
          setOptions(exclude ? users.filter((u) => !exclude(u)) : users);
        })
        .catch(() => {
          if (token === latest.current) setOptions([]);
        })
        .finally(() => {
          if (token === latest.current) setSearching(false);
        });
    }, 300);
  };

  const shown = value && !options.some((u) => u.id === value.id) ? [value, ...options] : options;
  return (
    <Select
      showSearch={{ filterOption: false, onSearch }}
      value={value?.id}
      placeholder={placeholder}
      onChange={(id: string) => onChange(shown.find((u) => u.id === id))}
      notFoundContent={searching ? <Spin size="small" /> : null}
      options={shown.map((u) => ({
        value: u.id,
        label: u.display_name ? `${u.display_name} · ${u.email}` : u.email,
      }))}
      aria-label={ariaLabel}
      style={style}
    />
  );
}

